  "implementation": "def solve(case):
    # Build node lookup and children
    nodes = {n['id']: n for n in case['nodes']}
    children = {nid: [] for nid in nodes}
    for nid, n in nodes.items():
        p = n['parent']
        if p is not None:
            children[p].append(nid)

    # Required symbols set for fast lookup
    required = set(case['required_symbols'])

    # Candidates: removable, not root, symbol not required
    candidates = []
    for nid, n in nodes.items():
        if n['parent'] is not None and n['removable'] and n['symbol'] not in required:
            candidates.append((n['depth'], nid))
    # Sort by depth descending, then by id ascending (lexicographic)
    candidates.sort(key=lambda x: (-x[0], x[1]))

    removed = set()
    removed_order = []

    for depth, nid in candidates:
        if nid in removed:
            continue
        node = nodes[nid]
        # Check if node has any child still present (not removed)
        has_retained_child = False
        for cid in children.get(nid, []):
            if cid not in removed:
                has_retained_child = True
                break
        if has_retained_child:
            continue
        # Remove this node (and its already removed subtree)
        removed.add(nid)
        removed_order.append(nid)

    retained = sorted([nid for nid in nodes if nid not in removed])
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained
    }"
